from pathlib import Path
from html.parser import HTMLParser
import json,hashlib,re
p=Path(__file__).parent
class Parser(HTMLParser):
 def __init__(self):super().__init__();self.pre=0;self.blocks=[];self.buf=[]
 def handle_starttag(self,t,attrs):
  if t=='pre':self.pre+=1;self.buf=[]
 def handle_endtag(self,t):
  if t=='pre'and self.pre:self.pre-=1;self.blocks.append(''.join(self.buf))
 def handle_data(self,s):
  if self.pre:self.buf.append(s)
a=Parser();a.feed((p/'qiita.html').read_text());article='\n'.join(a.blocks);old=(p/'7f77a51.cpp').read_text();current=(p.parent/'baseline/String/RollingHash.cpp').read_text();compact=lambda s:re.sub(r'\s+','',s)
patterns={'31bit_split':'a>>31','30bit_cross_split':'mid>>30','old_raw_expression':'au*bu*2+midu+(midd<<31)+ad*bd','positive_multiple':'MOD*4'}
rows={k:{'article_code':v in compact(article),'old_7f77a51':v in compact(old),'current_baseline':v in compact(current)}for k,v in patterns.items()}
assert all(x['article_code']and x['old_7f77a51']and not x['current_baseline']for x in rows.values())
out=dict(status='PASS',article_blocks=len(a.blocks),article_extracted_code_sha256=hashlib.sha256(article.encode()).hexdigest(),patterns=rows,note='短い演算パターンの対応を確認。全文同一や全体の翻訳元を証明しない。現標準経路も数学的には4p補正を使うため、旧定数名の不一致を補正方法そのものの不使用とは解釈しない。旧版のprefix初期値1は履歴で観察した事実であり、本文スニペットと同一とは主張しない。')
(p/'structural_comparison.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print('pattern comparison PASS')
